function fsVal(field) {
  if (!field) return null;
  if (field.stringValue  !== undefined) return field.stringValue;
  if (field.integerValue !== undefined) return Number(field.integerValue);
  if (field.doubleValue  !== undefined) return field.doubleValue;
  if (field.booleanValue !== undefined) return field.booleanValue;
  if (field.nullValue    !== undefined) return null;
  if (field.mapValue) {
    const out = {};
    for (const [k, v] of Object.entries(field.mapValue.fields || {})) out[k] = fsVal(v);
    return out;
  }
  if (field.arrayValue) return (field.arrayValue.values || []).map(fsVal);
  return null;
}

const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json;
  if (!body || !body.document) continue;
  const nameParts = body.document.name.split('/');
  const id = nameParts[nameParts.length - 1];
  const fields = body.document.fields || {};
  const lead = { id };
  for (const [k, v] of Object.entries(fields)) lead[k] = fsVal(v);

  // Safety guard: skip anything that looks like a test row rather than a
  // real prospect. yardi_export.py doesn't filter these out upstream (the
  // "Jay Test"/"Justin Test" rows Justin already flagged as a loose end
  // sitting in the export sheet) -- without this, a leftover test row would
  // get a real email sent to it the moment it synced into Firestore.
  const hay = [lead.company, lead.contact, lead.first_name, lead.email].join(' ').toLowerCase();
  if (/\btest\b/.test(hay)) continue;
  if (!lead.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email)) continue;

  results.push({ json: lead });
}

return results;

const lead = $json;

// Workflow 32 writes location as "{property} ({address})" (or just
// "{property}" if no address was on file) -- split it apart so we can use
// just the property name. Per Justin's ask (2026-08-18), the qualifying
// email names the location only, not the street address.
const loc = String(lead.location || '').trim();
const m = /^(.*?)\s*\(([^)]+)\)\s*$/.exec(loc);
const property = (m ? m[1] : loc).trim();
const address = m ? m[2].trim() : '';

const locationLine = property
  ? ('I saw you inquired about our ' + property + " location. To make sure that's the right fit, could you confirm your square footage needs and target move-in timeline?")
  : 'To point you to the right place, could you share your location preference, square footage needs, and target move-in timeline?';

// Escape user/lead-sourced text before dropping it into HTML -- this now
// renders as HTML (needed for the signature below), so it needs the same
// basic escaping any HTML-emitting template would use.
function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Justin's real signature, matched to his actual Outlook signature
// (screenshot confirmed 2026-08-18): name/title in the same blue accent,
// address, cell, the Cubework logo (hosted on cubework.com -- confirmed via
// a real 200/binary-image response, not a hosted 404, so it renders for the
// recipient even though this sandbox's own network can't preview it), and
// the same italic confidentiality notice used on manual sends. An automated
// Graph send has no client-side Outlook signature to fall back on, so this
// has to be in the body itself.
const signatureHtml = [
  '<div>&nbsp;</div>',
  '<div style="color:#1155CC;font-weight:bold;">Justin Cho | Business Development Executive</div>',
  '<div>218 Machlin Ct. | Walnut | California | 91789 | United States of America</div>',
  '<div style="font-size:9pt;">Cell: +1 (657) -620-7016</div>',
  '<div style="margin-top:6px;"><img src="https://www.cubework.com/logo/cubework-logo.svg" alt="Cubework" style="height:26px;display:block;"></div>',
  '<div style="font-size:9pt;font-style:italic;margin-top:6px;">NOTICE: This message, and any attachments, contain(s) information that may be confidential or protected by privilege from disclosure and is intended only for the individual or entity named above. No one else may disclose copy, distribute, or use the contents of this message for any purpose. Its unauthorized use, dissemination, or duplication is strictly prohibited and may be unlawful. If you receive this message in error or are not an authorized recipient, please immediately delete the message and any attachments and notify the sender.</div>'
].join('');

// Body is Sales/Templates/First-Touch Qualifying Email Template.md verbatim
// (General variant, location-known branch), now as HTML instead of plain
// text so the signature above can actually render (added 2026-08-18).
const body = [
  '<div style="font-family:Aptos,Calibri,Helvetica,sans-serif;font-size:12pt;color:rgb(0,0,0)">',
  '<div>Hello,</div>',
  '<div>&nbsp;</div>',
  "<div>Thanks for reaching out. My name is Justin, and I'm a Business Development Executive at Cubework.</div>",
  '<div>&nbsp;</div>',
  '<div>At Cubework, we offer flexible lease terms and a range of full-service amenities designed to support your business:</div>',
  '<div>&nbsp;</div>',
  '<div>* Fully furnished, professionally staffed facilities<br>* 24/7 access<br>* Flexible lease terms<br>* Water, coffee, and tea<br>* Basic utilities (electricity, water)<br>* Free Wi-Fi (office areas, breakrooms)<br>* Shared loading docks<br>* CCTV security<br>* Janitorial services<br>* Trash/dumpster service</div>',
  '<div>&nbsp;</div>',
  '<div>Additional Services (Not included in pricing):</div>',
  '<div>&nbsp;</div>',
  '<div>* Forklift rentals<br>* Secure Wi-Fi (warehouse)<br>* Electrical outlet installation (warehouse)</div>',
  '<div>&nbsp;</div>',
  '<div>' + escapeHtml(locationLine) + '</div>',
  '<div>&nbsp;</div>',
  '<div>Best,</div>',
  signatureHtml,
  '</div>'
].join('');

// FLAG FOR JUSTIN: the source template has no subject of its own since it's
// normally used as a manual reply. This is a cold automated send instead, so
// it needs one -- confirm/adjust before trusting this live.
const subject = 'Re: Your inquiry about Cubework' + (property ? (' ' + property) : '');

return [{ json: {
  leadId: lead.id,
  to: lead.email,
  subject,
  body,
  property,
  address
} }];

const rendered = $('Render qualifying email').item.json;
const draft = $('Create draft message').item.json || {};
const lead  = $('Loop pending leads').first().json;

// Graph's webLink comes back in a form that fails with "This message might
// have been moved or deleted" -- see resolve_thread.nodes.js / index.html's
// fixThreadUrl() for the full story. Reusing the exact same fix here so a
// thread we link ourselves opens the same way a manually-resolved one does.
function fixThreadUrl(u) {
  if (!u || typeof u !== 'string') return u;
  const m = /[?&]ItemID=([^&]+)/i.exec(u);
  if (!m) return u.replace(/^(https?:\/\/)outlook\.cloud\.microsoft\//i, '$1outlook.office365.com/');
  const itemId = m[1];
  const pathId = itemId.replace(/%2F/gi, '-').replace(/%2B/gi, '-');
  return 'https://outlook.office365.com/mail/deeplink/read/' + pathId + '?ItemID=' + itemId + '&exvsurl=1';
}

const now = new Date().toISOString();
const webLink = fixThreadUrl(draft.webLink || '');

// Same email_links shape the app already renders (see leadThreadConversationId
// / renderEmailLinks in index.html) -- pre-resolved at send time instead of
// going through the workflow-11 subject/contact search, since we already
// know exactly which message this is.
const newLink = {
  id: 'el' + Date.now(),
  label: 'Qualifying email',
  subject: rendered.subject,
  contact: rendered.to,
  url: webLink,
  conversationId: draft.conversationId || '',
  graphMessageId: draft.id || ''
};
const existingLinks = Array.isArray(lead.email_links) ? lead.email_links : [];

const newEntry = {
  id: 'e' + Date.now(),
  text: 'Sent first-touch qualifying email (auto, General template)' + (rendered.property ? (' re: ' + rendered.property + ' location.') : '.') + ' Asked to confirm sqft needs and move-in timeline.',
  kind: 'email',
  type: 'wait',
  dir: 'out',
  done: false,
  createdAt: now
};
const existingEntries = Array.isArray(lead.entries) ? lead.entries : [];

// Minimal JS -> Firestore REST value encoder -- just the shapes this doc
// actually uses (string / bool / null / array-of-object / object).
function toFs(v) {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === 'boolean') return { booleanValue: v };
  if (typeof v === 'number') return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
  if (Array.isArray(v)) return { arrayValue: { values: v.map(toFs) } };
  if (typeof v === 'object') {
    const fields = {};
    for (const [k, val] of Object.entries(v)) fields[k] = toFs(val);
    return { mapValue: { fields } };
  }
  return { stringValue: String(v) };
}

const patchFields = {
  qualifying_email_status: toFs('sent'),
  qualifying_email_sent_at: toFs(now),
  updatedAt: toFs(now),
  email_links: toFs([...existingLinks, newLink]),
  entries: toFs([...existingEntries, newEntry])
};

return [{ json: {
  leadId: lead.id,
  patchBody: { fields: patchFields },
  updateMask: Object.keys(patchFields).join('&updateMask.fieldPaths='),
  contact: lead.contact || lead.company || rendered.to,
  company: lead.company || '',
  property: rendered.property
} }];
